export interface Saint {
  id: string;
  name: string;
  feastDay: string;
  feastName: string;
  biography: string;
  quote: string;
  patronage: string;
  bornDied?: string;
  canonization?: string;
  imageGradient: string;
  symbol: string;
}

const saints: Saint[] = [
  { id: "mary-mother-of-god", name: "Mary, Mother of God", feastDay: "01-01", feastName: "Solemnity of Mary, Mother of God", biography: "The Blessed Virgin Mary, Mother of Jesus Christ, is honored as the greatest of all saints. Her faithful 'yes' to God's plan of salvation made the Incarnation possible. The Church celebrates her as Theotokos, the God-bearer, a title affirmed at the Council of Ephesus in 431.", quote: "Behold, I am the handmaid of the Lord; let it be done to me according to your word.", patronage: "All humanity, mothers", bornDied: "1st century BC/AD", canonization: "Pre-congregation", imageGradient: "from-blue-500 via-blue-400 to-sky-300", symbol: "M" },
  { id: "basil-gregory", name: "Saints Basil the Great & Gregory Nazianzen", feastDay: "01-02", feastName: "Memorial of Saints Basil the Great and Gregory Nazianzen", biography: "Basil the Great (329–379) was Bishop of Caesarea and a foundational father of Eastern monasticism. Gregory Nazianzen (329–390) was Archbishop of Constantinople and renowned for his theological orations on the Trinity. Together they shaped Christian doctrine and defended the Nicene faith.", quote: "A tree is known by its fruit; a Christian by their deeds.", patronage: "Hospital administrators, reformers", bornDied: "329–379 / 329–390", canonization: "Pre-congregation", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "B" },
  { id: "genevieves", name: "Saint Genevieve", feastDay: "01-03", feastName: "Memorial of Saint Genevieve", biography: "Genevieve was born in Nanterre near Paris around 422. Through her prayer and leadership, she inspired Parisians to resist Attila the Hun. She became the patron saint of Paris and is remembered for her deep faith, prophetic visions, and charitable works.", quote: "Trust in God, and He will protect you.", patronage: "Paris, against fever and plague", bornDied: "c. 422–512", canonization: "Pre-congregation", imageGradient: "from-teal-600 via-teal-500 to-emerald-400", symbol: "G" },
  { id: "elizabeth-ann-seton", name: "Saint Elizabeth Ann Seton", feastDay: "01-04", feastName: "Memorial of Saint Elizabeth Ann Seton", biography: "Born in New York in 1774, Elizabeth became the first native-born American saint. After her husband's death, she converted to Catholicism and founded the Sisters of Charity of St. Joseph, establishing the first Catholic parochial school in the United States.", quote: "The first end I propose in our daily work is to do the will of God; secondly, to do it in the manner He wills; and thirdly, to do it because it is His will.", patronage: "Catholic schools, orphans, widows", bornDied: "1774–1821", canonization: "1975", imageGradient: "from-emerald-600 via-emerald-500 to-green-400", symbol: "E" },
  { id: "john-neumann", name: "Saint John Neumann", feastDay: "01-05", feastName: "Memorial of Saint John Neumann", biography: "Born in Bohemia in 1811, John Neumann emigrated to the United States and became the fourth Bishop of Philadelphia. He was known for his tireless pastoral work, founding the first Catholic diocesan school system in America, and his devotion to the Eucharist.", quote: "The love of Christ urges us on to labor without ceasing for the salvation of souls.", patronage: "Catholic education, immigrants", bornDied: "1811–1860", canonization: "1977", imageGradient: "from-red-600 via-red-500 to-rose-400", symbol: "J" },
  { id: "andre-bessette", name: "Saint André Bessette", feastDay: "01-06", feastName: "Memorial of Saint André Bessette", biography: "A humble Holy Cross brother, André served as doorkeeper at Notre Dame College in Montreal for decades. Despite little education, he became known for miraculous healings through devotion to St. Joseph and was instrumental in building St. Joseph's Oratory.", quote: "When you go to St. Joseph, do not forget to speak to him of me, and I will speak to him of you.", patronage: "The sick, the poor, doorkeepers", bornDied: "1845–1937", canonization: "2010", imageGradient: "from-sky-700 via-sky-600 to-blue-500", symbol: "A" },
  { id: "raymond-penyafort", name: "Saint Raymond of Penyafort", feastDay: "01-07", feastName: "Memorial of Saint Raymond of Penyafort", biography: "A Spanish Dominican, Raymond was a renowned canon lawyer who compiled the Decretals of Gregory IX. He served as Master General of the Dominican Order and is remembered for his wisdom, humility, and dedication to missionary work, particularly among Muslims and Jews.", quote: "We must love our neighbor as ourselves, and this love must be expressed in action.", patronage: "Canon lawyers, lawyers", bornDied: "1175–1275", canonization: "1601", imageGradient: "from-indigo-600 via-indigo-500 to-purple-400", symbol: "R" },
  { id: "apollinaris", name: "Saint Apollinaris", feastDay: "01-08", feastName: "Memorial of Saint Apollinaris", biography: "An early Christian apologist and bishop of Hierapolis, Apollinaris defended the faith against paganism and heresy in the 2nd century. His writings, though mostly lost, were highly regarded by early Church historians.", quote: "Faith is the foundation of all good things and the seal of our salvation.", patronage: "Apologists", bornDied: "2nd century", canonization: "Pre-congregation", imageGradient: "from-cyan-600 via-cyan-500 to-teal-400", symbol: "A" },
  { id: "adrian-canterbury", name: "Saint Adrian of Canterbury", feastDay: "01-09", feastName: "Memorial of Saint Adrian of Canterbury", biography: "A North African monk who became abbot of a monastery near Naples, Adrian was appointed by Pope Vitalian to accompany Theodore of Tarsus to England. As abbot of SS. Peter and Paul in Canterbury, he established a renowned school that became a center of learning.", quote: "Knowledge without wisdom is like a sword in the hand of a fool.", patronage: "Scholars, teachers", bornDied: "c. 635–710", canonization: "Pre-congregation", imageGradient: "from-fuchsia-600 via-fuchsia-500 to-pink-400", symbol: "A" },
  { id: "gregory-nyssa", name: "Saint Gregory of Nyssa", feastDay: "01-10", feastName: "Memorial of Saint Gregory of Nyssa", biography: "Brother of Basil the Great, Gregory was Bishop of Nyssa and one of the Cappadocian Fathers who defended orthodox Trinitarian theology. His mystical writings profoundly shaped Christian spirituality and the understanding of the soul's journey toward God.", quote: "The goal of a virtuous life is to become like God.", patronage: "Mystical theology", bornDied: "c. 335–395", canonization: "Pre-congregation", imageGradient: "from-violet-700 via-violet-600 to-indigo-500", symbol: "G" },
  { id: "margaret-bourgeoys", name: "Saint Margaret Bourgeoys", feastDay: "01-12", feastName: "Memorial of Saint Margaret Bourgeoys", biography: "Born in France in 1620, Margaret founded the Congregation of Notre Dame in Montreal, educating poor children and young women in the colony. She crossed the Atlantic multiple times, established schools, and is remembered as a pioneer of education in New France.", quote: "It seems to me that God is all that is needed, and that God suffices.", patronage: "Teachers, the poor", bornDied: "1620–1700", canonization: "1982", imageGradient: "from-orange-600 via-orange-500 to-amber-400", symbol: "M" },
  { id: "hilary-poitiers", name: "Saint Hilary of Poitiers", feastDay: "01-13", feastName: "Memorial of Saint Hilary of Poitiers", biography: "A 4th-century bishop and Doctor of the Church, Hilary vigorously defended the divinity of Christ against Arianism. His theological works, particularly 'On the Trinity,' earned him the title 'Athanasius of the West.' He was exiled for his orthodoxy but continued writing.", quote: "The Trinity is the one God, and the one God is the Trinity.", patronage: "Against heresy", bornDied: "c. 310–367", canonization: "Pre-congregation", imageGradient: "from-lime-600 via-lime-500 to-green-400", symbol: "H" },
  { id: "macrina", name: "Saint Macrina the Younger", feastDay: "01-14", feastName: "Memorial of Saint Macrina the Younger", biography: "The elder sister of Basil the Great and Gregory of Nyssa, Macrina transformed the family estate into a monastic community. She is remembered as a wise spiritual guide whose philosophical dialogues with Gregory, recorded in his 'On the Soul and Resurrection,' show her profound theological insight.", quote: "The soul, when it has put off all earthly desires, becomes pure light.", patronage: "Monastics, widows", bornDied: "c. 327–379", canonization: "Pre-congregation", imageGradient: "from-emerald-700 via-emerald-600 to-green-500", symbol: "M" },
  { id: "paul-hermit", name: "Saint Paul the Hermit", feastDay: "01-15", feastName: "Memorial of Saint Paul the Hermit", biography: "Considered the first Christian hermit, Paul fled persecution in the 3rd century and lived in the Egyptian desert for nearly a century, sustained by a raven that brought him bread each day. Saint Anthony the Great visited him in his old age and buried him.", quote: "Blessed is the man who endures temptation, for when he has stood the test, he will receive the crown of life.", patronage: "Hermits, weavers", bornDied: "c. 227–341", canonization: "Pre-congregation", imageGradient: "from-stone-600 via-stone-500 to-zinc-400", symbol: "P" },
  { id: "anthony-egypt", name: "Saint Anthony the Great", feastDay: "01-17", feastName: "Memorial of Saint Anthony the Great", biography: "The father of Christian monasticism, Anthony abandoned his wealth in 270 to live in the Egyptian desert. His spiritual struggles against demonic temptation became legendary, inspiring countless others to embrace the monastic life. Athanasius's 'Life of Anthony' spread his influence across Christendom.", quote: "I saw the snares that the enemy spreads out over the world, and I said, 'Who can pass through these?' And I heard a voice saying, 'Humility.'", patronage: "Monks, against skin diseases", bornDied: "251–356", canonization: "Pre-congregation", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "A" },
  { id: "fabian-sebastian", name: "Saints Fabian & Sebastian", feastDay: "01-20", feastName: "Memorial of Saints Fabian and Sebastian", biography: "Fabian was pope from 236–250, martyred under Decius. Sebastian was a Roman soldier martyred under Diocletian, traditionally shot with arrows yet surviving, only to be beaten to death. Both are remembered for their steadfast witness to Christ.", quote: "Do not be afraid of those who kill the body but cannot kill the soul.", patronage: "Soldiers, against plague (Sebastian)", bornDied: "3rd century", canonization: "Pre-congregation", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "S" },
  { id: "agnes-rome", name: "Saint Agnes of Rome", feastDay: "01-21", feastName: "Memorial of Saint Agnes of Rome", biography: "A young Roman virgin martyred at age 12 or 13 during Diocletian's persecution. Agnes refused to marry and remained faithful to Christ, enduring torture with remarkable courage. Her name means 'lamb,' and she is depicted with a lamb, symbolizing purity and sacrifice.", quote: "Christ is my spouse: He I have loved, He I seek, He I serve.", patronage: "Young girls, engaged couples, virgins", bornDied: "c. 291–304", canonization: "Pre-congregation", imageGradient: "from-pink-500 via-pink-400 to-rose-300", symbol: "A" },
  { id: "vincent-pallotti", name: "Saint Vincent Pallotti", feastDay: "01-22", feastName: "Memorial of Saint Vincent Pallotti", biography: "An Italian priest who founded the Society of the Catholic Apostolate (Pallottines). Vincent dedicated his life to rekindling faith among the laity and clergy, organizing missions and charitable works throughout Rome. His vision emphasized the universal call to apostolate for all Christians.", quote: "The love of Christ impels us to extend the Kingdom of God everywhere.", patronage: "The Pallottines, lay apostolate", bornDied: "1795–1850", canonization: "1963", imageGradient: "from-sky-600 via-sky-500 to-blue-400", symbol: "V" },
  { id: "francis-sales", name: "Saint Francis de Sales", feastDay: "01-24", feastName: "Memorial of Saint Francis de Sales", biography: "Bishop of Geneva and Doctor of the Church, Francis de Sales is known for his gentle approach to evangelization and his spiritual classic 'Introduction to the Devout Life.' He co-founded the Order of the Visitation with St. Jane Frances de Chantal.", quote: "Do not wish to be anything other than what you are, but be that perfectly.", patronage: "Writers, journalists, the deaf", bornDied: "1567–1622", canonization: "1665", imageGradient: "from-blue-600 via-blue-500 to-indigo-400", symbol: "F" },
  { id: "paul-conversion", name: "Conversion of Saint Paul", feastDay: "01-25", feastName: "Feast of the Conversion of Saint Paul", biography: "Once a fierce persecutor of Christians, Saul of Tarsus was struck blind on the road to Damascus and encountered the risen Christ. He converted, was baptized, and became the greatest missionary of the early Church, writing 13 epistles that form a cornerstone of Christian theology.", quote: "It is no longer I who live, but Christ who lives in me.", patronage: "Missions, theologians, evangelists", bornDied: "c. 5–67", canonization: "Pre-congregation", imageGradient: "from-rose-600 via-rose-500 to-red-400", symbol: "P" },
  { id: "timothy-titus", name: "Saints Timothy & Titus", feastDay: "01-26", feastName: "Memorial of Saints Timothy and Titus", biography: "Timothy and Titus were close companions of St. Paul and early bishops of the Church. Timothy served as bishop of Ephesus, Titus as bishop of Crete. Paul's letters to them contain essential pastoral guidance for Church leadership.", quote: "Let no one despise your youth, but set the believers an example in speech and conduct, in love, in faith, in purity.", patronage: "Bishops", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-lime-700 via-lime-600 to-green-500", symbol: "T" },
  { id: "angela-merici", name: "Saint Angela Merici", feastDay: "01-27", feastName: "Memorial of Saint Angela Merici", biography: "Founder of the Company of St. Ursula (Ursulines), the first teaching order of women in the Church. Angela dedicated her life to educating poor girls, establishing a revolutionary model of religious life where sisters lived in their own homes rather than convents.", quote: "Let your heart be on fire with the love of God, and you will never be cold.", patronage: "Teachers, the sick", bornDied: "1474–1540", canonization: "1807", imageGradient: "from-purple-600 via-purple-500 to-fuchsia-400", symbol: "A" },
  { id: "thomas-aquinas", name: "Saint Thomas Aquinas", feastDay: "01-28", feastName: "Memorial of Saint Thomas Aquinas", biography: "The Angelic Doctor, Thomas Aquinas was the greatest theologian of the medieval Church. His Summa Theologica synthesized Aristotelian philosophy with Christian revelation. A Dominican friar, he wrote extensively on metaphysics, ethics, and the sacraments.", quote: "To one who has faith, no explanation is necessary. To one without faith, no explanation is possible.", patronage: "Students, universities, theologians", bornDied: "1225–1274", canonization: "1323", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "T" },
  { id: "john-bosco", name: "Saint John Bosco", feastDay: "01-31", feastName: "Memorial of Saint John Bosco", biography: "Don Bosco dedicated his life to educating poor and abandoned youth in Turin. He founded the Salesians and developed the preventive system of education based on reason, religion, and kindness. His educational approach and miraculous dreams continue to inspire.", quote: "It is enough that you are young for me to love you.", patronage: "Youth, students, apprentices", bornDied: "1815–1888", canonization: "1934", imageGradient: "from-teal-600 via-teal-500 to-cyan-400", symbol: "B" },
  { id: "brigid-kildare", name: "Saint Brigid of Kildare", feastDay: "02-01", feastName: "Memorial of Saint Brigid of Kildare", biography: "One of Ireland's three patron saints, Brigid founded the monastic community at Kildare, the first double monastery for men and women in Ireland. Known for her generosity and compassion, she is associated with many miracles involving food and healing.", quote: "I would like the angels of heaven to be among us and to sing with us.", patronage: "Ireland, poets, healers", bornDied: "c. 451–525", canonization: "Pre-congregation", imageGradient: "from-green-600 via-green-500 to-emerald-400", symbol: "B" },
  { id: "presentation-lord", name: "Presentation of the Lord", feastDay: "02-02", feastName: "Feast of the Presentation of the Lord", biography: "Forty days after Christmas, Mary and Joseph presented Jesus in the Temple, where Simeon and Anna recognized Him as the Messiah. This feast, also called Candlemas, celebrates Christ as the Light of the World and the fulfillment of God's promise.", quote: "My eyes have seen your salvation, which you have prepared in the presence of all peoples.", patronage: "Light, purification", bornDied: "c. 4 BC", canonization: "Feast of the Lord", imageGradient: "from-yellow-500 via-yellow-400 to-gold-300", symbol: "P" },
  { id: "blase", name: "Saint Blaise", feastDay: "02-03", feastName: "Memorial of Saint Blaise", biography: "Bishop of Sebaste in Armenia, Blaise was martyred in 316. He is best known for the blessing of throats on his feast day, stemming from a legend where he saved a child choking on a fishbone. His intercession is invoked against throat ailments.", quote: "Blessed are they who suffer persecution for justice's sake.", patronage: "Throat ailments, wool workers", bornDied: "d. 316", canonization: "Pre-congregation", imageGradient: "from-rose-600 via-rose-500 to-red-400", symbol: "B" },
  { id: "agatha", name: "Saint Agatha", feastDay: "02-05", feastName: "Memorial of Saint Agatha", biography: "A young Christian virgin from Catania, Sicily, Agatha was tortured and martyred under Emperor Decius for refusing to renounce her faith. Her steadfast courage made her one of the most venerated early martyrs, and she is named in the Roman Canon.", quote: "Jesus Christ, Lord of all, You see my heart, You know my desire. I belong to You.", patronage: "Breast cancer, Sicily", bornDied: "c. 231–251", canonization: "Pre-congregation", imageGradient: "from-pink-600 via-pink-500 to-rose-400", symbol: "A" },
  { id: "paul-miki", name: "Saint Paul Miki & Companions", feastDay: "02-06", feastName: "Memorial of Saint Paul Miki and Companions", biography: "Paul Miki was a Japanese Jesuit and twenty-five companions martyred in Nagasaki in 1597. Crucified and speared, they became the first martyrs of East Asia. Paul preached from the cross, forgiving his executioners and proclaiming the faith.", quote: "I forgive my persecutors completely; I pray that God will grant them the grace of baptism.", patronage: "Japan", bornDied: "1562–1597", canonization: "1862", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "P" },
  { id: "jerome-emiliani", name: "Saint Jerome Emiliani", feastDay: "02-08", feastName: "Memorial of Saint Jerome Emiliani", biography: "A Venetian soldier turned priest, Jerome dedicated his life to caring for orphans, the sick, and the poor after his own conversion. He founded the Somascan Order and is remembered for his heroic charity during plague and famine.", quote: "Do not tire of giving to the poor; the Lord will repay you a hundredfold.", patronage: "Orphans, abandoned children", bornDied: "1481–1537", canonization: "1767", imageGradient: "from-slate-600 via-slate-500 to-gray-400", symbol: "J" },
  { id: "scholastica", name: "Saint Scholastica", feastDay: "02-10", feastName: "Memorial of Saint Scholastica", biography: "The twin sister of St. Benedict, Scholastica founded a community of nuns near Monte Cassino. Her deep love for God was so intense that, during her final visit with Benedict, she prayed for a storm to prolong their conversation. She is the patroness of Benedictine nuns.", quote: "I asked you to stay with me, and you would not listen. So I asked my Lord, and He heard me.", patronage: "Nuns, Benedictine women", bornDied: "c. 480–547", canonization: "Pre-congregation", imageGradient: "from-purple-600 via-purple-500 to-violet-400", symbol: "S" },
  { id: "our-lady-lourdes", name: "Our Lady of Lourdes", feastDay: "02-11", feastName: "Feast of Our Lady of Lourdes", biography: "In 1858, the Blessed Virgin Mary appeared eighteen times to St. Bernadette Soubirous in Lourdes, France. Mary identified herself as 'the Immaculate Conception' and instructed Bernadette to dig a spring, which became a source of miraculous healings. Lourdes is one of the world's most visited pilgrimage sites.", quote: "I am the Immaculate Conception. Go, drink at the spring and wash yourself there.", patronage: "The sick, bodily ills", bornDied: "Appeared 1858", canonization: "Apparition approved 1862", imageGradient: "from-blue-500 via-blue-400 to-sky-300", symbol: "M" },
  { id: "cyril-methodius", name: "Saints Cyril & Methodius", feastDay: "02-14", feastName: "Memorial of Saints Cyril and Methodius", biography: "Brothers from Thessalonica who evangelized the Slavic peoples in the 9th century. Cyril created the Glagolitic alphabet, the precursor to Cyrillic, translating the Bible and liturgy into Slavic. They are co-patrons of Europe and pioneers of inculturation.", quote: "Let us glorify the Lord in every language, for He has given us all the same Spirit.", patronage: "Europe, ecumenism", bornDied: "826–869 / 815–885", canonization: "1880", imageGradient: "from-indigo-700 via-indigo-600 to-purple-500", symbol: "C" },
  { id: "thomas-akempis", name: "Blessed Thomas à Kempis", feastDay: "02-15", feastName: "Memorial of Blessed Thomas à Kempis", biography: "A German-Dutch canon regular and mystical writer, Thomas is widely regarded as the author of 'The Imitation of Christ,' the most widely read Christian devotional work after the Bible. His writings emphasize humility, simplicity, and the interior life.", quote: "What good does it do to speak learnedly about the Trinity if, lacking humility, you displease the Trinity?", patronage: "Spiritual reading", bornDied: "1380–1471", canonization: "Beatified 1827", imageGradient: "from-stone-700 via-stone-600 to-zinc-500", symbol: "T" },
  { id: "chair-peter", name: "Chair of Saint Peter", feastDay: "02-22", feastName: "Feast of the Chair of Saint Peter", biography: "This feast celebrates the apostolic authority of Peter and his successors as Bishops of Rome. The 'chair' symbolizes the teaching authority of the Pope, the visible foundation of Church unity. The feast dates back to the 4th century.", quote: "You are Peter, and upon this rock I will build my Church, and the gates of Hades shall not prevail against it.", patronage: "Unity of the Church", bornDied: "1st century", canonization: "Apostolic feast", imageGradient: "from-orange-600 via-orange-500 to-amber-400", symbol: "P" },
  { id: "polycarp", name: "Saint Polycarp of Smyrna", feastDay: "02-23", feastName: "Memorial of Saint Polycarp", biography: "A disciple of St. John the Evangelist and Bishop of Smyrna, Polycarp was one of the Apostolic Fathers. At age 86, he was martyred by burning, declaring, 'Eighty-six years I have served Him, and He has done me no wrong. How can I blaspheme my King and Savior?'", quote: "Eighty-six years I have served Him, and He has done me no wrong. How can I blaspheme my King and Savior?", patronage: "Against earaches, martyrs", bornDied: "c. 69–155", canonization: "Pre-congregation", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "P" },
  { id: "katharine-drexel", name: "Saint Katharine Drexel", feastDay: "03-03", feastName: "Memorial of Saint Katharine Drexel", biography: "Born into a wealthy Philadelphia family, Katharine used her inheritance to fund missions and schools for Native American and African American communities. She founded the Sisters of the Blessed Sacrament and established Xavier University in New Orleans.", quote: "The patient and humble endurance of the cross—whatever nature it may be—is the highest work we have to do.", patronage: "Racial justice, philanthropists", bornDied: "1858–1955", canonization: "2000", imageGradient: "from-sky-700 via-sky-600 to-blue-500", symbol: "K" },
  { id: "casimir", name: "Saint Casimir of Poland", feastDay: "03-04", feastName: "Memorial of Saint Casimir", biography: "Prince of Poland, Casimir lived a life of exceptional holiness, refusing to marry for political reasons and dedicating himself to prayer, fasting, and charity. He died young at 26 and is remembered for his purity and devotion to Mary.", quote: "Live in such a way that when you die, you may say, 'I have fought the good fight, I have finished the race.'", patronage: "Poland, Lithuania, youth", bornDied: "1458–1484", canonization: "1521", imageGradient: "from-cyan-700 via-cyan-600 to-teal-500", symbol: "C" },
  { id: "perpetua-felicity", name: "Saints Perpetua & Felicity", feastDay: "03-07", feastName: "Memorial of Saints Perpetua and Felicity", biography: "Young mothers and catechumens martyred in Carthage in 203. Perpetua's prison diary is one of the earliest Christian writings by a woman. Felicity, pregnant at the time, gave birth in prison before being thrown to wild beasts. Their courage inspired the African Church.", quote: "We are not left to ourselves; we are in the hands of God.", patronage: "Mothers, prisoners", bornDied: "d. 203", canonization: "Pre-congregation", imageGradient: "from-rose-700 via-rose-600 to-red-500", symbol: "P" },
  { id: "john-god", name: "Saint John of God", feastDay: "03-08", feastName: "Memorial of Saint John of God", biography: "After a turbulent youth as a soldier, John converted and dedicated himself to caring for the mentally ill and the poor in Granada, Spain. He founded the Order of Hospitallers (Brothers of St. John of God) and is remembered for his radical charity and compassion.", quote: "Labor without stopping; do all the good works you can while you still have time.", patronage: "The sick, hospitals, nurses", bornDied: "1495–1550", canonization: "1690", imageGradient: "from-teal-700 via-teal-600 to-emerald-500", symbol: "J" },
  { id: "patrick", name: "Saint Patrick", feastDay: "03-17", feastName: "Feast of Saint Patrick", biography: "Captured by Irish raiders at 16, Patrick was enslaved for six years before escaping. He later returned as a missionary bishop, converting much of Ireland. Using the shamrock to explain the Trinity, he established monasteries and churches that became centers of Christian learning.", quote: "Christ with me, Christ before me, Christ behind me, Christ within me, Christ beneath me, Christ above me.", patronage: "Ireland, engineers, Nigeria", bornDied: "c. 385–461", canonization: "Pre-congregation", imageGradient: "from-green-700 via-green-600 to-emerald-500", symbol: "P" },
  { id: "joseph", name: "Saint Joseph", feastDay: "03-19", feastName: "Solemnity of Saint Joseph", biography: "The foster father of Jesus and husband of Mary, Joseph was a just and righteous man. Though not Jesus's biological father, he protected and provided for the Holy Family. Patron of the universal Church, workers, and a peaceful death, his silent example of faithful obedience inspires all.", quote: "When Joseph awoke from sleep, he did as the angel of the Lord commanded him.", patronage: "Universal Church, workers, fathers", bornDied: "1st century BC", canonization: "Pre-congregation", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "J" },
  { id: "benedict", name: "Saint Benedict of Nursia", feastDay: "03-21", feastName: "Memorial of Saint Benedict", biography: "The father of Western monasticism, Benedict wrote the Rule of Saint Benedict, which became the foundational guide for monastic life in Europe. His twin sister was Scholastica. Benedict's balanced approach to prayer, work, and community life shaped Western civilization.", quote: "Listen carefully, my son, to the master's instructions, and attend to them with the ear of your heart.", patronage: "Europe, monks, schoolchildren", bornDied: "c. 480–547", canonization: "Pre-congregation", imageGradient: "from-lime-700 via-lime-600 to-green-500", symbol: "B" },
  { id: "turin-shroud", name: "The Holy Shroud of Turin", feastDay: "04-01", feastName: "Feast of the Holy Shroud", biography: "The Shroud of Turin is a linen cloth bearing the image of a crucified man, believed by many to be the burial cloth of Jesus Christ. It has been venerated since the Middle Ages and is kept in the Cathedral of St. John the Baptist in Turin, Italy.", quote: "He was wounded for our transgressions, crushed for our iniquities; upon Him was the punishment that made us whole.", patronage: "Devotion to the Passion", bornDied: "1st century", canonization: "Relic of the Church", imageGradient: "from-amber-800 via-amber-700 to-yellow-600", symbol: "S" },
  { id: "francis-paola", name: "Saint Francis of Paola", feastDay: "04-02", feastName: "Memorial of Saint Francis of Paola", biography: "Founder of the Minim friars, Francis lived an extreme life of humility and penance. Known for his miraculous powers, he served as counselor to King Louis XI and was renowned for his prophecy and healings. The Minims take a fourth vow of perpetual Lenten abstinence.", quote: "Charity is the bond of perfection and the fulfillment of the law.", patronage: "Sailors, the sick", bornDied: "1416–1507", canonization: "1519", imageGradient: "from-stone-600 via-stone-500 to-gray-400", symbol: "F" },
  { id: "vincent-ferrer", name: "Saint Vincent Ferrer", feastDay: "04-05", feastName: "Memorial of Saint Vincent Ferrer", biography: "A Spanish Dominican preacher, Vincent traveled across Western Europe preaching repentance and conversion. Known as the 'Angel of the Judgment,' he was instrumental in ending the Western Schism and is remembered for his powerful sermons that drew thousands.", quote: "The greatest charity we can show our neighbor is to lead them to the truth.", patronage: "Builders, plumbers", bornDied: "1350–1419", canonization: "1455", imageGradient: "from-orange-700 via-orange-600 to-amber-500", symbol: "V" },
  { id: "john-baptist-salle", name: "Saint John Baptist de La Salle", feastDay: "04-07", feastName: "Memorial of Saint John Baptist de La Salle", biography: "Founder of the Brothers of the Christian Schools, de La Salle revolutionized education by training teachers, establishing free schools for the poor, and introducing classroom teaching in the vernacular. He is the patron saint of teachers.", quote: "The teacher who does not love their students will never be able to inspire them.", patronage: "Teachers, educators", bornDied: "1659–1719", canonization: "1900", imageGradient: "from-blue-700 via-blue-600 to-indigo-500", symbol: "J" },
  { id: "julian-norwich", name: "Blessed Julian of Norwich", feastDay: "05-08", feastName: "Memorial of Blessed Julian of Norwich", biography: "An English anchorite and mystic, Julian lived in a cell attached to St. Julian's Church in Norwich. Her 'Revelations of Divine Love,' based on sixteen visions of the crucified Christ, is the first known book written by a woman in English. She is a beloved spiritual guide.", quote: "All shall be well, and all shall be well, and all manner of thing shall be well.", patronage: "Mystics, spiritual writers", bornDied: "1342–1416", canonization: "Venerated (not formally canonized)", imageGradient: "from-pink-500 via-pink-400 to-rose-300", symbol: "J" },
  { id: "mark", name: "Saint Mark the Evangelist", feastDay: "04-25", feastName: "Feast of Saint Mark the Evangelist", biography: "Companion of Peter and Paul, Mark wrote the first Gospel, likely based on Peter's testimony. He founded the Church of Alexandria, where he was martyred. His symbol is the winged lion. His Gospel emphasizes Jesus as the suffering Son of Man.", quote: "The kingdom of God has come near; repent and believe the Good News!", patronage: "Venice, notaries, lions", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "M" },
  { id: "catherine-siena", name: "Saint Catherine of Siena", feastDay: "04-29", feastName: "Memorial of Saint Catherine of Siena", biography: "A lay Dominican and Doctor of the Church, Catherine was a mystic and theologian who influenced popes and worked tirelessly for Church unity during the Avignon papacy. Her 'Dialogue' is a spiritual classic. She is co-patron of Italy and Europe.", quote: "Be who God meant you to be and you will set the world on fire.", patronage: "Italy, Europe, nurses", bornDied: "1347–1380", canonization: "1461", imageGradient: "from-orange-600 via-orange-500 to-amber-400", symbol: "C" },
  { id: "pius-v", name: "Saint Pius V", feastDay: "04-30", feastName: "Memorial of Saint Pius V", biography: "Pope from 1566–1572, Pius V implemented the reforms of the Council of Trent, published the Roman Missal (Tridentine Mass), and organized the Holy League that defeated the Ottoman fleet at Lepanto. He was a Dominican known for his personal austerity.", quote: "The rosary is the weapon for these times.", patronage: "Dominicans, the Rosary", bornDied: "1504–1572", canonization: "1712", imageGradient: "from-slate-700 via-slate-600 to-gray-500", symbol: "P" },
  { id: "joseph-worker", name: "Saint Joseph the Worker", feastDay: "05-01", feastName: "Feast of Saint Joseph the Worker", biography: "Established by Pope Pius XII in 1955 to Christianize the labor movement and honor the dignity of work. Joseph, the carpenter of Nazareth, exemplifies the sanctity of ordinary labor. This feast aligns with International Workers' Day.", quote: "Whatever you do, work heartily, as for the Lord and not for men.", patronage: "Workers, artisans, carpenters", bornDied: "1st century BC", canonization: "Feast instituted 1955", imageGradient: "from-stone-700 via-stone-600 to-zinc-500", symbol: "J" },
  { id: "athanasius", name: "Saint Athanasius of Alexandria", feastDay: "05-02", feastName: "Memorial of Saint Athanasius", biography: "The great defender of orthodox Trinitarian doctrine against Arianism. As Bishop of Alexandria, Athanasius was exiled five times for his unwavering faith. His 'Life of Anthony' popularized monasticism, and his theological works shaped the Nicene Creed.", quote: "The Son of God became man so that we might become God.", patronage: "Theologians, orthodoxy", bornDied: "296–373", canonization: "Pre-congregation", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "A" },
  { id: "philip-james", name: "Saints Philip & James", feastDay: "05-03", feastName: "Feast of Saints Philip and James", biography: "Philip was one of the first apostles called by Jesus. James the Less was the first Bishop of Jerusalem and author of the Epistle of James. Both were martyred for their faith. The feast celebrates their apostolic witness and contributions to the early Church.", quote: "Show me your faith without works, and I will show you my faith by my works.", patronage: "Uruguay, hat makers", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-teal-600 via-teal-500 to-cyan-400", symbol: "P" },
  { id: "monica", name: "Saint Monica of Hippo", feastDay: "05-04", feastName: "Memorial of Saint Monica", biography: "The mother of St. Augustine, Monica prayed tirelessly for her son's conversion for 17 years. Her patience and persistent faith were ultimately rewarded when Augustine converted and became one of the Church's greatest theologians. She is a model of persevering prayer.", quote: "Nothing is far from God, and do not doubt that He will hear your prayers.", patronage: "Mothers, wives, those with troubled children", bornDied: "331–387", canonization: "Pre-congregation", imageGradient: "from-purple-700 via-purple-600 to-fuchsia-500", symbol: "M" },
  { id: "augustine-canterbury", name: "Saint Augustine of Canterbury", feastDay: "05-27", feastName: "Memorial of Saint Augustine of Canterbury", biography: "Sent by Pope Gregory the Great to evangelize the Anglo-Saxons, Augustine established Christianity in southern England. He became the first Archbishop of Canterbury and founded the cathedral there. His mission successfully converted King Ethelbert and thousands.", quote: "The harvest is plentiful, but the laborers are few.", patronage: "England", bornDied: "d. 604", canonization: "Pre-congregation", imageGradient: "from-blue-700 via-blue-600 to-indigo-500", symbol: "A" },
  { id: "matthias", name: "Saint Matthias", feastDay: "05-14", feastName: "Feast of Saint Matthias", biography: "Chosen by lot to replace Judas Iscariot as the twelfth apostle, Matthias had been a follower of Jesus from His baptism to His ascension. He preached the gospel and was martyred, traditionally by crucifixion in Jerusalem or Colchis.", quote: "May his place be taken by another who is a witness to the resurrection.", patronage: "Carpenters, tailors", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-cyan-600 via-cyan-500 to-teal-400", symbol: "M" },
  { id: "isidore-farmer", name: "Saint Isidore the Farmer", feastDay: "05-15", feastName: "Memorial of Saint Isidore the Farmer", biography: "A poor farm laborer from Madrid, Isidore was known for his piety and generosity. Legend says angels helped him plow his fields while he prayed. He is the patron of farmers and rural communities, canonized alongside St. Ignatius Loyola and others.", quote: "Work and pray, for the Lord is with those who labor.", patronage: "Farmers, laborers, Madrid", bornDied: "1070–1130", canonization: "1622", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "I" },
  { id: "pope-gregory-vii", name: "Pope Saint Gregory VII", feastDay: "05-25", feastName: "Memorial of Pope Saint Gregory VII", biography: "Hildebrand, who became Pope Gregory VII, was a reforming pope who fought against simony and lay investiture. He asserted papal authority in the Investiture Controversy against Emperor Henry IV. His reforms strengthened the Church's spiritual independence.", quote: "The Church must be free to fulfill her mission, subject to no earthly power.", patronage: "Reformers", bornDied: "1015–1085", canonization: "1606", imageGradient: "from-slate-800 via-slate-700 to-gray-600", symbol: "G" },
  { id: "bede", name: "Saint Bede the Venerable", feastDay: "05-25", feastName: "Memorial of Saint Bede the Venerable", biography: "An English Benedictine monk, scholar, and Doctor of the Church, Bede wrote the 'Ecclesiastical History of the English People,' the primary source for early English history. He also wrote biblical commentaries and treatises on astronomy and chronology.", quote: "I have always found it sweet to learn, to teach, and to write.", patronage: "Scholars, historians", bornDied: "672–735", canonization: "1899 (confirmed Doctor)", imageGradient: "from-lime-600 via-lime-500 to-green-400", symbol: "B" },
  { id: "mary-help-christians", name: "Mary, Help of Christians", feastDay: "05-24", feastName: "Feast of Mary, Help of Christians", biography: "A title of the Blessed Virgin Mary venerated particularly in the Catholic Church, promoted by St. John Bosco and the Salesians. The feast celebrates Mary's intercession and protection, especially for the Church in times of trial. The Basilica of Mary Help of Christians stands in Turin.", quote: "Mary, Help of Christians, pray for us who have recourse to thee.", patronage: "Salesians, Australia, China", bornDied: "Marian title", canonization: "Marian devotion", imageGradient: "from-sky-600 via-sky-500 to-blue-400", symbol: "M" },
  { id: "philip-neri", name: "Saint Philip Neri", feastDay: "05-26", feastName: "Memorial of Saint Philip Neri", biography: "Known as the 'Apostle of Rome,' Philip founded the Oratory and dedicated his life to the spiritual renewal of Rome through informal gatherings of prayer, music, and conversation. His joyful holiness, humor, and care for the poor attracted countless followers.", quote: "Cheerfulness strengthens the heart and makes us persevere in a good life.", patronage: "Rome, joy, humor", bornDied: "1515–1595", canonization: "1622", imageGradient: "from-rose-600 via-rose-500 to-pink-400", symbol: "P" },
  { id: "mary-queen", name: "Queenship of Mary", feastDay: "05-31", feastName: "Feast of the Queenship of Mary", biography: "Established by Pope Pius XII in 1954, this feast celebrates Mary's royal dignity as Mother of Christ the King. Mary's queenship is rooted in her unique role in salvation history — she humbly served as the Mother of God and reigns with her Son in heaven.", quote: "He has cast down the mighty from their thrones and has lifted up the lowly.", patronage: "Heavenly intercession", bornDied: "Marian feast", canonization: "Feast established 1954", imageGradient: "from-yellow-500 via-gold-400 to-amber-300", symbol: "M" },
  { id: "justin-martyr", name: "Saint Justin Martyr", feastDay: "06-01", feastName: "Memorial of Saint Justin Martyr", biography: "A Greek philosopher who converted to Christianity, Justin became the first great Christian apologist. He defended the faith in his writings, blending Greek philosophy with Christian revelation. He was martyred in Rome by beheading around 165 AD.", quote: "No one can rightly prefer the false to the true, nor the evil to the good.", patronage: "Philosophers, apologists", bornDied: "c. 100–165", canonization: "Pre-congregation", imageGradient: "from-indigo-600 via-indigo-500 to-purple-400", symbol: "J" },
  { id: "charles-lwanga", name: "Saint Charles Lwanga & Companions", feastDay: "06-03", feastName: "Memorial of Saint Charles Lwanga and Companions", biography: "Twenty-two Ugandan martyrs, Catholic and Anglican, who were burned to death on the orders of King Mwanga II in 1886 for refusing to renounce Christianity. Charles, the chief of the royal pages, led them in faith and courage.", quote: "You can burn our bodies, but you cannot harm our souls. We die for the love of God.", patronage: "African youth, Uganda", bornDied: "1860–1886", canonization: "1964", imageGradient: "from-red-800 via-red-700 to-rose-600", symbol: "C" },
  { id: "boniface", name: "Saint Boniface", feastDay: "06-05", feastName: "Memorial of Saint Boniface", biography: "The 'Apostle of Germany,' Boniface was an English Benedictine monk who evangelized the Germanic tribes. He famously felled the Oak of Thor at Geismar to demonstrate the power of Christ. He was martyred while confirming converts in Frisia.", quote: "Let us be armed with the shield of faith and the sword of the Spirit.", patronage: "Germany, brewers, tailors", bornDied: "675–754", canonization: "Pre-congregation", imageGradient: "from-amber-800 via-amber-700 to-yellow-600", symbol: "B" },
  { id: "ephrem", name: "Saint Ephrem the Syrian", feastDay: "06-09", feastName: "Memorial of Saint Ephrem", biography: "A Syriac deacon, theologian, and Doctor of the Church, Ephrem composed thousands of hymns that beautifully express the Christian faith. Called the 'Harp of the Holy Spirit,' his poetic theology profoundly influenced Eastern Christian spirituality.", quote: "Lord, give me a heart that can see You in every person I meet.", patronage: "Spiritual directors, poets", bornDied: "c. 306–373", canonization: "Pre-congregation", imageGradient: "from-lime-700 via-lime-600 to-green-500", symbol: "E" },
  { id: "barnabas", name: "Saint Barnabas", feastDay: "06-11", feastName: "Memorial of Saint Barnabas", biography: "A Levite from Cyprus, Barnabas was an early Christian missionary and companion of Paul. Known as the 'Son of Encouragement,' he introduced Paul to the apostles and accompanied him on the first missionary journey. He was martyred at Salamis.", quote: "He was a good man, full of the Holy Spirit and faith.", patronage: "Cyprus, peacemakers", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-teal-700 via-teal-600 to-emerald-500", symbol: "B" },
  { id: "anthony-padua", name: "Saint Anthony of Padua", feastDay: "06-13", feastName: "Memorial of Saint Anthony of Padua", biography: "A Portuguese Franciscan friar and Doctor of the Church, Anthony was renowned as a powerful preacher and miracle worker. His profound knowledge of Scripture earned him the title 'Evangelical Doctor.' He is invoked for finding lost items.", quote: "Actions speak louder than words; let your words teach and your actions speak.", patronage: "Lost items, the poor, travelers", bornDied: "1195–1231", canonization: "1232", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "A" },
  { id: "albert-chmielowski", name: "Saint Albert Chmielowski", feastDay: "06-17", feastName: "Memorial of Saint Albert Chmielowski", biography: "A Polish painter who abandoned his art to serve the homeless and destitute. He founded the Albertine Brothers and Sisters, caring for the poorest of the poor in Krakow. His radical witness inspired the young Karol Wojtyla (Pope John Paul II).", quote: "The love of God is the most beautiful art of all.", patronage: "The homeless, artists", bornDied: "1845–1916", canonization: "1989", imageGradient: "from-stone-700 via-stone-600 to-gray-500", symbol: "A" },
  { id: "john-baptist", name: "Nativity of Saint John the Baptist", feastDay: "06-24", feastName: "Solemnity of the Nativity of Saint John the Baptist", biography: "The only saint whose birth is celebrated as a solemnity (besides Mary and Jesus). John was the divinely-appointed forerunner of Christ, baptizing in the Jordan and calling for repentance. He prepared the way for the Messiah and was martyred by Herod.", quote: "He must increase, I must decrease.", patronage: "Conversion, baptisms", bornDied: "1st century BC/AD", canonization: "Pre-congregation", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "J" },
  { id: "peter-paul", name: "Saints Peter and Paul", feastDay: "06-29", feastName: "Solemnity of Saints Peter and Paul", biography: "Peter, the fisherman called by Christ to be the rock of the Church, and Paul, the converted persecutor who became the Apostle to the Gentiles. Both were martyred in Rome under Nero. Their combined witness forms the foundation of the universal Church.", quote: "You are the Christ, the Son of the living God. (Peter) — I have fought the good fight, I have finished the race. (Paul)", patronage: "Rome, the universal Church", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "P" },
  { id: "first-martyrs-rome", name: "First Martyrs of the Holy Roman Church", feastDay: "06-30", feastName: "Memorial of the First Martyrs of the Church of Rome", biography: "Christians martyred in Nero's persecution after the Great Fire of Rome in 64 AD. They were crucified, burned as torches, or fed to wild beasts in the Circus of Nero. Their heroic witness, witnessed by Peter and Paul, was the seed of the Roman Church.", quote: "The blood of martyrs is the seed of the Church.", patronage: "Perseverance in faith", bornDied: "d. 64", canonization: "Pre-congregation", imageGradient: "from-red-900 via-red-800 to-rose-700", symbol: "M" },
  { id: "thomas", name: "Saint Thomas the Apostle", feastDay: "07-03", feastName: "Feast of Saint Thomas the Apostle", biography: "Known as 'Doubting Thomas' for his initial skepticism about the Resurrection, his confession 'My Lord and my God' became a profound declaration of faith. He evangelized India and is revered by the St. Thomas Christians of Kerala. He was martyred near Chennai.", quote: "My Lord and my God!", patronage: "India, architects, the doubtful", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-blue-800 via-blue-700 to-indigo-600", symbol: "T" },
  { id: "elizabeth-portugal", name: "Saint Elizabeth of Portugal", feastDay: "07-04", feastName: "Memorial of Saint Elizabeth of Portugal", biography: "A queen known for her peacemaking and charity. Named after her great-aunt St. Elizabeth of Hungary, she mediated conflicts between her husband and son, and between kingdoms. She distributed her wealth to the poor and cared for the sick.", quote: "Peace is the greatest treasure one can possess.", patronage: "Peacemakers, Portugal", bornDied: "1271–1336", canonization: "1625", imageGradient: "from-pink-700 via-pink-600 to-rose-500", symbol: "E" },
  { id: "benedict-moor", name: "Saint Benedict the Moor", feastDay: "07-04", feastName: "Memorial of Saint Benedict the Moor", biography: "Born of African slaves in Sicily, Benedict joined the Franciscans and became a renowned spiritual leader despite being illiterate. He served as superior of his community and was known for his wisdom, miracles, and deep prayer life.", quote: "The Lord does not look at our abilities but at our hearts.", patronage: "African Americans, Palermo", bornDied: "1526–1589", canonization: "1807", imageGradient: "from-stone-800 via-stone-700 to-zinc-600", symbol: "B" },
  { id: "cyril-methodius-slavorum", name: "Saints Cyril and Methodius", feastDay: "07-05", feastName: "Feast of Saints Cyril and Methodius (Slavic)", biography: "The brothers from Thessalonica who brought Christianity to the Slavic peoples. Cyril invented the Glagolitic alphabet and translated Scripture into Old Church Slavonic. They are venerated as co-patrons of Europe and pioneers of missionary inculturation.", quote: "Let us proclaim the Gospel in every language, for all peoples are called to salvation.", patronage: "Europe, ecumenism, Slavic peoples", bornDied: "826–869 / 815–885", canonization: "Pre-congregation", imageGradient: "from-purple-800 via-purple-700 to-violet-600", symbol: "C" },
  { id: "maria-goretti", name: "Saint Maria Goretti", feastDay: "07-06", feastName: "Memorial of Saint Maria Goretti", biography: "An Italian girl of 11 who was stabbed to death while defending her purity. Before dying, she forgave her attacker. Her murderer attended her canonization in 1950. She is the youngest canonized saint and a powerful witness to chastity and forgiveness.", quote: "I forgive him and I want him to be with me in paradise.", patronage: "Youth, purity, rape victims", bornDied: "1890–1902", canonization: "1950", imageGradient: "from-pink-400 via-pink-300 to-rose-200", symbol: "M" },
  { id: "augustine-zhao", name: "Saint Augustine Zhao Rong & Companions", feastDay: "07-09", feastName: "Memorial of Saint Augustine Zhao Rong and Companions", biography: "A Chinese priest and 119 companions (including laypeople, catechists, and children) who were martyred in China between 1648 and 1930. They represent the resilient faith of the Chinese Catholic Church through centuries of persecution.", quote: "The faith planted in China will bear fruit a hundredfold.", patronage: "China", bornDied: "1746–1815 / various", canonization: "2000", imageGradient: "from-red-800 via-red-700 to-rose-600", symbol: "A" },
  { id: "benedict-nursia-translation", name: "Saint Benedict of Nursia (Translation)", feastDay: "07-11", feastName: "Feast of Saint Benedict", biography: "The father of Western monasticism. His Rule of Saint Benedict transformed European civilization and spirituality. The translation of his relics to the Abbey of Fleury in France is commemorated on this date. Benedict's balance of prayer, work, and community life remains a model.", quote: "Let peace be your quest and your aim.", patronage: "Europe, monks, civil engineers", bornDied: "c. 480–547", canonization: "Pre-congregation", imageGradient: "from-green-700 via-green-600 to-emerald-500", symbol: "B" },
  { id: "henry", name: "Saint Henry", feastDay: "07-13", feastName: "Memorial of Saint Henry", biography: "Holy Roman Emperor Henry II was a ruler dedicated to Church reform and missionary work. He founded the Diocese of Bamberg and supported monastic life. Despite his power, he remained humble, frequently praying and serving the poor.", quote: "What use is earthly glory if it does not serve the glory of God?", patronage: "Benedictine oblates, rulers", bornDied: "973–1024", canonization: "1146", imageGradient: "from-indigo-700 via-indigo-600 to-purple-500", symbol: "H" },
  { id: "kateri-tekakwitha", name: "Saint Kateri Tekakwitha", feastDay: "07-14", feastName: "Memorial of Saint Kateri Tekakwitha", biography: "Known as the 'Lily of the Mohawks,' Kateri was a Mohawk-Algonquin woman who converted to Christianity and lived a life of prayer, penance, and care for the sick. She refused to marry on her faith, dedicating herself to Christ. She is the first Native American saint.", quote: "Who can tell me what is the most pleasing to God that I may do it?", patronage: "Indigenous peoples, ecology, Canada", bornDied: "1656–1680", canonization: "2012", imageGradient: "from-cyan-700 via-cyan-600 to-teal-500", symbol: "K" },
  { id: "bonaventure", name: "Saint Bonaventure", feastDay: "07-15", feastName: "Memorial of Saint Bonaventure", biography: "A Franciscan theologian and Doctor of the Church, Bonaventure was known as the 'Seraphic Doctor.' He wrote extensively on mystical theology and the life of St. Francis. He served as Cardinal-Bishop of Albano and helped unite the Greek and Latin churches at the Council of Lyons.", quote: "In all things, let us seek the source of all good: the goodness of God.", patronage: "Theologians, Bowel disorders", bornDied: "1217–1274", canonization: "1482", imageGradient: "from-orange-700 via-orange-600 to-amber-500", symbol: "B" },
  { id: "our-lady-mount-carmel", name: "Our Lady of Mount Carmel", feastDay: "07-16", feastName: "Feast of Our Lady of Mount Carmel", biography: "The Blessed Virgin Mary under the title associated with the Carmelite Order. Tradition holds that the Scapular of Mount Carmel was given to St. Simon Stock by Mary as a sign of her protection. The feast celebrates Mary's maternal care and the Carmelite spiritual heritage.", quote: "Take this scapular; whoever dies wearing it shall not suffer eternal fire.", patronage: "Carmelites, protection", bornDied: "Marian feast", canonization: "Marian devotion", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "M" },
  { id: "margaret-antioch", name: "Saint Margaret of Antioch", feastDay: "07-20", feastName: "Memorial of Saint Margaret of Antioch", biography: "A 4th-century virgin martyr, Margaret was tortured and beheaded for refusing to renounce her faith. Legend says she burst from the belly of a dragon (the devil) by the sign of the cross. She is one of the Fourteen Holy Helpers.", quote: "The power of Christ dissolves every snare of the enemy.", patronage: "Childbirth, pregnant women", bornDied: "c. 289–304", canonization: "Pre-congregation", imageGradient: "from-rose-700 via-rose-600 to-red-500", symbol: "M" },
  { id: "mary-magdalene", name: "Saint Mary Magdalene", feastDay: "07-22", feastName: "Feast of Saint Mary Magdalene", biography: "A devoted disciple of Jesus from whom He cast out seven demons. Mary Magdalene stood faithfully at the foot of the cross and was the first witness to the Resurrection, earning her the title 'Apostle to the Apostles.' Her feast is celebrated as a solemnity.", quote: "I have seen the Lord!", patronage: "Penitents, contemplatives, women", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-orange-500 via-orange-400 to-amber-300", symbol: "M" },
  { id: "james-apostle", name: "Saint James the Greater", feastDay: "07-25", feastName: "Feast of Saint James the Greater", biography: "The brother of John and one of the first apostles called by Jesus. James witnessed the Transfiguration and the Agony in the Garden. He preached in Spain before being martyred by Herod Agrippa I. The pilgrimage to Santiago de Compostela is dedicated to him.", quote: "Can you drink the cup that I am going to drink?", patronage: "Spain, pilgrims, laborers", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "J" },
  { id: "joachim-anne", name: "Saints Joachim and Anne", feastDay: "07-26", feastName: "Memorial of Saints Joachim and Anne", biography: "The parents of the Virgin Mary and grandparents of Jesus. Though not mentioned in Scripture, early Christian tradition names them Joachim and Anne. They are honored for their faithful preparation of Mary for her unique role in salvation history.", quote: "Blessed are those who raise children in the love of God.", patronage: "Grandparents, parents, couples", bornDied: "1st century BC", canonization: "Pre-congregation", imageGradient: "from-teal-600 via-teal-500 to-cyan-400", symbol: "A" },
  { id: "lazarus", name: "Saints Martha, Mary, and Lazarus", feastDay: "07-29", feastName: "Memorial of Saints Martha, Mary, and Lazarus", biography: "The beloved siblings of Bethany who were close friends of Jesus. Martha served, Mary listened, and Lazarus was raised from the dead after four days. Their home in Bethany was a place of rest and refuge for Jesus during His ministry.", quote: "I am the resurrection and the life; whoever believes in me, even if he dies, will live.", patronage: "Servants, cooks, the dead", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-green-600 via-green-500 to-emerald-400", symbol: "M" },
  { id: "peter-chrysologus", name: "Saint Peter Chrysologus", feastDay: "07-30", feastName: "Memorial of Saint Peter Chrysologus", biography: "Bishop of Ravenna and Doctor of the Church, Peter earned the title 'Golden-Worded' for his eloquent and concise sermons. He was a staunch defender of orthodox Christology against the Monophysite heresy and emphasized the Incarnation in his preaching.", quote: "He who yearns for the bread of Christ becomes the bread of Christ.", patronage: "Preachers, orators", bornDied: "c. 380–450", canonization: "Pre-congregation", imageGradient: "from-lime-700 via-lime-600 to-green-500", symbol: "P" },
  { id: "ignatius-loyola", name: "Saint Ignatius of Loyola", feastDay: "07-31", feastName: "Memorial of Saint Ignatius of Loyola", biography: "Founder of the Society of Jesus (Jesuits), Ignatius was a Spanish knight who converted after being wounded in battle. His Spiritual Exercises transformed Christian spirituality. The Jesuits became the vanguard of Catholic education and missionary work worldwide.", quote: "Go forth and set the world on fire.", patronage: "Spiritual exercises, soldiers", bornDied: "1491–1556", canonization: "1622", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "I" },
  { id: "alphonsus-liguori", name: "Saint Alphonsus Liguori", feastDay: "08-01", feastName: "Memorial of Saint Alphonsus Liguori", biography: "Founder of the Redemptorists, Bishop, and Doctor of the Church. Alphonsus was a prolific writer on moral theology and spirituality. His works on the sacraments and the Blessed Virgin remain influential. He dedicated his life to preaching missions to the rural poor.", quote: "Do not neglect the means of salvation because they seem small; great trees grow from small seeds.", patronage: "Confessors, moralists, vocations", bornDied: "1696–1787", canonization: "1839", imageGradient: "from-blue-700 via-blue-600 to-indigo-500", symbol: "A" },
  { id: "ezequiel-moreno", name: "Saint Ezequiel Moreno y Díaz", feastDay: "08-02", feastName: "Memorial of Saint Ezequiel Moreno", biography: "An Augustinian Recollect bishop who served as a missionary in the Philippines and later as Bishop of Pasto, Colombia. He is remembered for his tireless pastoral work, defense of the Church, and devotion to Our Lady of the Rosary.", quote: "Pray the Rosary every day, and you will have peace in your family.", patronage: "Cancer patients, Philippines", bornDied: "1848–1906", canonization: "1992", imageGradient: "from-sky-700 via-sky-600 to-blue-500", symbol: "E" },
  { id: "john-vianney", name: "Saint John Vianney", feastDay: "08-04", feastName: "Memorial of Saint John Vianney", biography: "The Curé of Ars, John Vianney was a humble parish priest known for his extraordinary preaching, spiritual counsel, and miracles. He spent 16–18 hours daily in the confessional, transforming Ars into a pilgrimage destination. He is the patron saint of parish priests.", quote: "The priesthood is the love of the heart of Jesus.", patronage: "Parish priests, confessors", bornDied: "1786–1859", canonization: "1925", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "J" },
  { id: "transfiguration", name: "The Transfiguration of the Lord", feastDay: "08-06", feastName: "Feast of the Transfiguration of the Lord", biography: "Jesus revealed His divine glory to Peter, James, and John on Mount Tabor. Moses and Elijah appeared, speaking of His impending exodus in Jerusalem. A voice from the cloud declared, 'This is my beloved Son, listen to Him.' The feast dates to the 5th century.", quote: "Lord, it is good for us to be here.", patronage: "Contemplation", bornDied: "Feast of the Lord", canonization: "Feast of the Lord", imageGradient: "from-white via-yellow-200 to-gold-300", symbol: "T" },
  { id: "sixtus-ii", name: "Pope Saint Sixtus II & Companions", feastDay: "08-07", feastName: "Memorial of Pope Saint Sixtus II and Companions", biography: "Pope Sixtus II and four deacons were martyred in 258 during Emperor Valerian's persecution. They were arrested while celebrating Mass in the catacombs and beheaded. St. Lawrence, the most famous of his deacons, was martyred three days later.", quote: "I will not abandon the flock entrusted to me by Christ.", patronage: "Rome", bornDied: "d. 258", canonization: "Pre-congregation", imageGradient: "from-slate-800 via-slate-700 to-gray-600", symbol: "S" },
  { id: "dominic", name: "Saint Dominic de Guzmán", feastDay: "08-08", feastName: "Memorial of Saint Dominic", biography: "Founder of the Order of Preachers (Dominicans), Dominic combined contemplative prayer with active preaching. He established an order dedicated to spreading truth through preaching, study, and the Rosary. His vision transformed the intellectual and spiritual life of the medieval Church.", quote: "Arm yourself with prayer rather than a sword; wear humility rather than fine clothes.", patronage: "Astronomers, preachers, the Rosary", bornDied: "1170–1221", canonization: "1234", imageGradient: "from-slate-600 via-slate-500 to-gray-400", symbol: "D" },
  { id: "edith-stein", name: "Saint Teresa Benedicta of the Cross (Edith Stein)", feastDay: "08-09", feastName: "Memorial of Saint Teresa Benedicta of the Cross", biography: "A German Jewish philosopher who converted to Catholicism and became a Carmelite nun. She was arrested by the Nazis and died at Auschwitz in 1942. Her intellectual work bridged phenomenology and Christian mysticism. She is a co-patron of Europe.", quote: "Do not accept anything as love which lacks truth, and do not accept anything as truth which lacks love.", patronage: "Europe, converts, martyrs", bornDied: "1891–1942", canonization: "1998", imageGradient: "from-fuchsia-700 via-fuchsia-600 to-purple-500", symbol: "T" },
  { id: "lawrence", name: "Saint Lawrence", feastDay: "08-10", feastName: "Feast of Saint Lawrence", biography: "One of the seven deacons of Rome, Lawrence was martyred in 258. When ordered to surrender the Church's treasures, he presented the poor, declaring, 'These are the Church's treasures.' He was grilled to death, famously telling his torturers, 'Turn me over, I'm done on this side.'", quote: "The poor are the treasures of the Church.", patronage: "Cooks, comedians, librarians", bornDied: "d. 258", canonization: "Pre-congregation", imageGradient: "from-orange-700 via-orange-600 to-amber-500", symbol: "L" },
  { id: "clare-assisi", name: "Saint Clare of Assisi", feastDay: "08-11", feastName: "Memorial of Saint Clare of Assisi", biography: "A noblewoman who followed St. Francis's example of poverty, founding the Poor Clares. Clare defended her community from invaders by holding the Eucharist. She is the patroness of television because of a vision in which she heard Mass from her sickbed.", quote: "Go forth in peace, for you have followed the good road.", patronage: "Television, embroiderers", bornDied: "1193–1253", canonization: "1255", imageGradient: "from-yellow-700 via-yellow-600 to-amber-500", symbol: "C" },
  { id: "maximilian-kolbe", name: "Saint Maximilian Kolbe", feastDay: "08-14", feastName: "Memorial of Saint Maximilian Kolbe", biography: "A Polish Franciscan friar who volunteered to die in place of a fellow prisoner at Auschwitz. He was canonized as a martyr of charity. Kolbe was also a missionary and publisher who promoted devotion to the Immaculate Virgin Mary through the Militia Immaculata.", quote: "Hatred destroys, love builds. No one can destroy love.", patronage: "Prisoners, journalists, pro-life", bornDied: "1894–1941", canonization: "1982", imageGradient: "from-gray-800 via-gray-700 to-zinc-600", symbol: "M" },
  { id: "assumption", name: "The Assumption of the Blessed Virgin Mary", feastDay: "08-15", feastName: "Solemnity of the Assumption of the Blessed Virgin Mary", biography: "The dogma proclaimed by Pope Pius XII in 1950 that Mary, having completed her earthly life, was assumed body and soul into heavenly glory. This feast celebrates the culmination of Mary's unique role in salvation and the hope of resurrection for all believers.", quote: "All generations will call me blessed, for the Mighty One has done great things for me.", patronage: "Hope, bodily assumption", bornDied: "Marian feast", canonization: "Dogma defined 1950", imageGradient: "from-blue-600 via-blue-500 to-sky-400", symbol: "M" },
  { id: "stephen-hungary", name: "Saint Stephen of Hungary", feastDay: "08-16", feastName: "Memorial of Saint Stephen of Hungary", biography: "The first King of Hungary, Stephen converted his people to Christianity and established the Hungarian Church. Crowned in 1000 AD, he promoted religious and social reform, built monasteries, and ensured justice for his subjects. He is the patron saint of Hungary.", quote: "I command you to be kind to all, and to remember that we are all of the same dust.", patronage: "Hungary, kings, stone masons", bornDied: "975–1038", canonization: "1083", imageGradient: "from-green-800 via-green-700 to-emerald-600", symbol: "S" },
  { id: "john-eudes", name: "Saint John Eudes", feastDay: "08-19", feastName: "Memorial of Saint John Eudes", biography: "A French missionary and founder of the Eudists and the Order of Our Lady of Charity. He was a pioneer in promoting devotion to the Sacred Hearts of Jesus and Mary. His work established seminaries and reformed clerical education in France.", quote: "The heart of Jesus is the source of all holiness and the model of all virtues.", patronage: "Missionaries, seminarians", bornDied: "1601–1680", canonization: "1925", imageGradient: "from-rose-700 via-rose-600 to-red-500", symbol: "J" },
  { id: "bernard", name: "Saint Bernard of Clairvaux", feastDay: "08-20", feastName: "Memorial of Saint Bernard of Clairvaux", biography: "A Cistercian abbot and Doctor of the Church, Bernard was the most influential spiritual writer of the 12th century. He preached the Second Crusade, defended orthodoxy against Abelard, and wrote profound commentaries on the Song of Songs. He is called the 'Mellifluous Doctor.'", quote: "What do I know of God, except that He is love?", patronage: "Cistercians, beekeepers", bornDied: "1090–1153", canonization: "1174", imageGradient: "from-lime-800 via-lime-700 to-green-600", symbol: "B" },
  { id: "pope-pius-x", name: "Pope Saint Pius X", feastDay: "08-21", feastName: "Memorial of Pope Saint Pius X", biography: "Pope from 1903–1914, Pius X is remembered for promoting Eucharistic piety by lowering the age of First Communion to seven (Quam Singulari). He combated modernism, reformed Church music, and reorganized the Roman Curia. His motto was 'To restore all things in Christ.'", quote: "Holy Communion is the shortest and safest way to heaven.", patronage: "First communicants, seminarians", bornDied: "1835–1914", canonization: "1954", imageGradient: "from-white via-slate-100 to-gray-200", symbol: "P" },
  { id: "queen-mary", name: "Queenship of the Blessed Virgin Mary", feastDay: "08-22", feastName: "Memorial of the Queenship of Mary", biography: "This memorial was established by Pope Pius XII in 1954. Mary's queenship flows from her divine maternity and her participation in Christ's redemptive work. She reigns as Queen of Heaven and Earth, ever interceding for her children.", quote: "Hail, Holy Queen, Mother of Mercy, our life, our sweetness, and our hope.", patronage: "Heavenly intercession", bornDied: "Marian feast", canonization: "Feast established 1954", imageGradient: "from-yellow-600 via-gold-500 to-amber-400", symbol: "M" },
  { id: "rose-lima", name: "Saint Rose of Lima", feastDay: "08-23", feastName: "Memorial of Saint Rose of Lima", biography: "The first canonized saint of the Americas, Rose was a lay Dominican known for her severe penances, deep prayer life, and care for the poor and sick in Lima, Peru. She lived in a garden hut and dedicated her life to Christ, experiencing mystical union with God.", quote: "Apart from the cross, there is no other ladder by which we may enter heaven.", patronage: "Peru, Americas, florists", bornDied: "1586–1617", canonization: "1671", imageGradient: "from-rose-600 via-rose-500 to-pink-400", symbol: "R" },
  { id: "bartholomew", name: "Saint Bartholomew the Apostle", feastDay: "08-24", feastName: "Feast of Saint Bartholomew", biography: "One of the twelve apostles, traditionally identified with Nathanael. He was known for his honesty and lack of guile. After Pentecost, he evangelized in India and Armenia, where he was martyred by being flayed alive and beheaded. He is honored in all Christian traditions.", quote: "Rabbi, you are the Son of God! You are the King of Israel!", patronage: "Armenia, bookbinders, tanners", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-red-800 via-red-700 to-rose-600", symbol: "B" },
  { id: "monica-hippo", name: "Saint Monica", feastDay: "08-27", feastName: "Memorial of Saint Monica", biography: "Mother of Augustine of Hippo, Monica's tears and prayers for her son's conversion spanned 17 years. Her persistent faith was rewarded when Augustine converted and became a Doctor of the Church. She died in Ostia while returning to Africa, her work complete.", quote: "Nothing is far from God, and do not doubt that He will hear your prayers.", patronage: "Mothers, those with troubled children", bornDied: "331–387", canonization: "Pre-congregation", imageGradient: "from-purple-700 via-purple-600 to-fuchsia-500", symbol: "M" },
  { id: "augustine-hippo", name: "Saint Augustine of Hippo", feastDay: "08-28", feastName: "Memorial of Saint Augustine of Hippo", biography: "One of the greatest theologians in Christian history, Augustine was Bishop of Hippo and Doctor of the Church. His 'Confessions' is the first Western autobiography and a profound spiritual classic. He shaped Western thought on grace, sin, and the Church.", quote: "You have made us for Yourself, O Lord, and our hearts are restless until they rest in You.", patronage: "Theologians, brewers, printers", bornDied: "354–430", canonization: "Pre-congregation", imageGradient: "from-blue-800 via-blue-700 to-indigo-600", symbol: "A" },
  { id: "beheading-john", name: "The Beheading of Saint John the Baptist", feastDay: "08-29", feastName: "Memorial of the Beheading of Saint John the Baptist", biography: "John the Baptist was imprisoned by Herod Antipas for condemning his marriage to Herodias. At Salome's request, Herod ordered John beheaded. The feast commemorates John's martyrdom and his faithful witness to the truth, even unto death.", quote: "I must decrease, so that He may increase.", patronage: "Converts, the persecuted", bornDied: "1st century BC/AD", canonization: "Pre-congregation", imageGradient: "from-red-800 via-red-700 to-rose-600", symbol: "J" },
  { id: "gregory-great", name: "Pope Saint Gregory the Great", feastDay: "09-03", feastName: "Memorial of Pope Saint Gregory the Great", biography: "Pope and Doctor of the Church, Gregory was a reformer, liturgist, and theologian. He sent Augustine of Canterbury to evangelize England, reformed the liturgy (Gregorian chant), and wrote 'Pastoral Rule.' He is one of the four great Latin Doctors.", quote: "The Scripture grows with those who read it.", patronage: "Musicians, teachers, popes", bornDied: "540–604", canonization: "Pre-congregation", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "G" },
  { id: "mother-teresa", name: "Saint Teresa of Calcutta", feastDay: "09-05", feastName: "Memorial of Saint Teresa of Calcutta", biography: "Born Anjezë Gonxhe Bojaxhiu in Albania, Teresa founded the Missionaries of Charity in Calcutta. She served the poorest of the poor, caring for the sick, dying, and abandoned. Awarded the Nobel Peace Prize in 1979, her radical love and service inspired the world.", quote: "Not all of us can do great things. But we can do small things with great love.", patronage: "World Youth Day, Missionaries of Charity", bornDied: "1910–1997", canonization: "2016", imageGradient: "from-white via-blue-100 to-blue-200", symbol: "T" },
  { id: "nativity-mary", name: "The Nativity of the Blessed Virgin Mary", feastDay: "09-08", feastName: "Feast of the Nativity of Mary", biography: "The Church celebrates the birth of the Virgin Mary, the daughter of Joachim and Anne. Her birth was the dawn of salvation, preparing the way for the Incarnation. The feast echoes the joy of her Immaculate Conception and her unique role as Mother of God.", quote: "Your birth, O Virgin Mother of God, brought joy to the whole world.", patronage: "New beginnings", bornDied: "Marian feast", canonization: "Marian feast", imageGradient: "from-pink-500 via-pink-400 to-rose-300", symbol: "M" },
  { id: "peter-claver", name: "Saint Peter Claver", feastDay: "09-09", feastName: "Memorial of Saint Peter Claver", biography: "A Spanish Jesuit who dedicated 40 years to ministering to enslaved Africans arriving in Cartagena, Colombia. He baptized over 300,000 people and cared for their physical and spiritual needs. He is the patron of African missions and interracial justice.", quote: "We must speak to the poor with our hands before we speak with our lips.", patronage: "African missions, slaves, Colombia", bornDied: "1580–1654", canonization: "1888", imageGradient: "from-stone-800 via-stone-700 to-zinc-600", symbol: "P" },
  { id: "john-chrysostom", name: "Saint John Chrysostom", feastDay: "09-13", feastName: "Memorial of Saint John Chrysostom", biography: "Archbishop of Constantinople and Doctor of the Church, John was the greatest preacher of the early Church (Chrysostom = 'Golden-mouthed'). His bold preaching against corruption and his liturgical reforms deeply influenced both Eastern and Western Christianity.", quote: "The bee is more honored than other animals, not because she works, but because she works for others.", patronage: "Preachers, Constantinople", bornDied: "347–407", canonization: "Pre-congregation", imageGradient: "from-gold-600 via-gold-500 to-amber-400", symbol: "J" },
  { id: "holy-cross", name: "Exaltation of the Holy Cross", feastDay: "09-14", feastName: "Feast of the Exaltation of the Holy Cross", biography: "Commemorating the recovery of the True Cross by St. Helena in 326 and its restoration to Jerusalem after Persian capture in 629. The feast lifts high the Cross as the instrument of salvation, turning the symbol of death into the sign of victory.", quote: "We adore You, O Christ, and we praise You, because by Your holy Cross You have redeemed the world.", patronage: "Redemption", bornDied: "Feast of the Lord", canonization: "Feast of the Lord", imageGradient: "from-red-800 via-red-700 to-rose-600", symbol: "C" },
  { id: "our-lady-sorrows", name: "Our Lady of Sorrows", feastDay: "09-15", feastName: "Memorial of Our Lady of Sorrows", biography: "The devotion reflecting on seven sorrows of the Virgin Mary: Simeon's prophecy, the flight into Egypt, loss of Jesus in the Temple, meeting Jesus on the Via Dolorosa, standing at the cross, receiving Jesus' body, and watching His burial. Mary's compassion unites her intimately with Christ's passion.", quote: "Standing by the cross of Jesus were His mother and His mother's sister.", patronage: "The sorrowful, Poland", bornDied: "Marian memorial", canonization: "Marian devotion", imageGradient: "from-violet-800 via-violet-700 to-purple-600", symbol: "M" },
  { id: "cornelius-cyprian", name: "Saints Cornelius & Cyprian", feastDay: "09-16", feastName: "Memorial of Saints Cornelius and Cyprian", biography: "Cornelius was pope (251–253) who opposed Novatianism and taught that the Church could reconcile lapsed Christians through penance. Cyprian was the eloquent Bishop of Carthage who defended Church unity and was martyred. Both died for the faith in 253/258.", quote: "Outside the Church there is no salvation. (Cyprian)", patronage: "Bishops", bornDied: "3rd century", canonization: "Pre-congregation", imageGradient: "from-slate-700 via-slate-600 to-gray-500", symbol: "C" },
  { id: "robert-bellarmine", name: "Saint Robert Bellarmine", feastDay: "09-17", feastName: "Memorial of Saint Robert Bellarmine", biography: "A Jesuit theologian, Cardinal, and Doctor of the Church, Bellarmine was a leading figure of the Counter-Reformation. He wrote extensively on Church authority and doctrine, and was a spiritual director. He defended the faith against Protestant positions with clarity and charity.", quote: "The Church is not a dead letter, but the living body of Christ.", patronage: "Catechists, canon lawyers", bornDied: "1542–1621", canonization: "1930", imageGradient: "from-purple-700 via-purple-600 to-violet-500", symbol: "R" },
  { id: "januarius", name: "Saint Januarius (San Gennaro)", feastDay: "09-19", feastName: "Memorial of Saint Januarius", biography: "Bishop of Benevento, Januarius was martyred in 305 during Diocletian's persecution. He is famous for the miracle of the liquefaction of his blood in Naples, which occurs three times each year. The relic of his blood is preserved in the Naples Cathedral.", quote: "The blood of martyrs is the witness of truth.", patronage: "Naples, blood banks", bornDied: "d. 305", canonization: "Pre-congregation", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "J" },
  { id: "andrew-kim", name: "Saints Andrew Kim Taegon & Paul Chong Hasang", feastDay: "09-20", feastName: "Memorial of Saints Andrew Kim Taegon and Paul Chong Hasang", biography: "The first Korean priest and martyr, Andrew Kim Taegon, along with Paul Chong Hasang and 101 companions, were martyred in Korea between 1839 and 1867. They represent the Korean Catholic Church's foundation through the blood of martyrs.", quote: "If you remain faithful, the Lord will reward you with eternal life.", patronage: "Korea, Korean Catholics", bornDied: "1821–1846 / 1795–1839", canonization: "1984", imageGradient: "from-red-900 via-red-800 to-rose-700", symbol: "A" },
  { id: "matthew", name: "Saint Matthew the Evangelist", feastDay: "09-21", feastName: "Feast of Saint Matthew the Evangelist", biography: "A tax collector who became one of the twelve apostles, Matthew wrote the first Gospel, emphasizing Jesus as the fulfillment of Old Testament prophecy. His Gospel was originally written in Aramaic for Jewish Christians. He is the patron of tax collectors and accountants.", quote: "Follow me. And he got up and followed Him.", patronage: "Accountants, tax collectors, bankers", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-amber-600 via-amber-500 to-yellow-400", symbol: "M" },
  { id: "padre-pio", name: "Saint Pio of Pietrelcina (Padre Pio)", feastDay: "09-23", feastName: "Memorial of Saint Pio of Pietrelcina", biography: "A Capuchin friar who bore the stigmata for 50 years. Padre Pio was known for his miracles, bilocation, prophetic insights, and healing through confession. He founded the Casa Sollievo della Sofferenza hospital. Millions were drawn to his Mass and spiritual counsel.", quote: "Pray, hope, and don't worry. Worry is useless. God is merciful and will hear your prayer.", patronage: "Healing, confessions, the sick", bornDied: "1887–1968", canonization: "2002", imageGradient: "from-stone-700 via-stone-600 to-zinc-500", symbol: "P" },
  { id: "cosmas-damian", name: "Saints Cosmas & Damian", feastDay: "09-26", feastName: "Memorial of Saints Cosmas and Damian", biography: "Twin brothers and physicians who practiced medicine without charging fees, earning them the title 'moneyless ones.' They were martyred in Syria under Diocletian by beheading. They are among the most venerated early martyrs and are invoked against disease.", quote: "Heal the sick freely, as you have received freely from God.", patronage: "Physicians, pharmacists, surgeons", bornDied: "d. 303", canonization: "Pre-congregation", imageGradient: "from-teal-700 via-teal-600 to-emerald-500", symbol: "C" },
  { id: "vincent-de-paul", name: "Saint Vincent de Paul", feastDay: "09-27", feastName: "Memorial of Saint Vincent de Paul", biography: "A French priest who dedicated his life to serving the poor. He founded the Congregation of the Mission (Vincentians) and the Daughters of Charity with St. Louise de Marillac. His organized approach to charity transformed the Church's ministry to the poor.", quote: "Go to the poor: you will find God.", patronage: "Charities, hospitals, volunteers", bornDied: "1581–1660", canonization: "1737", imageGradient: "from-blue-700 via-blue-600 to-indigo-500", symbol: "V" },
  { id: "wenceslaus", name: "Saint Wenceslaus", feastDay: "09-28", feastName: "Memorial of Saint Wenceslaus", biography: "Duke of Bohemia and martyr, Wenceslaus was a just and Christian ruler who was murdered by his brother Boleslaus. He is the patron saint of the Czech Republic and is celebrated for his faith, charity, and dedication to justice. 'Good King Wenceslaus' celebrates his legacy.", quote: "Let us love God and serve the poor, and God will provide for all our needs.", patronage: "Czech Republic, brewers", bornDied: "907–935", canonization: "Pre-congregation", imageGradient: "from-cyan-700 via-cyan-600 to-teal-500", symbol: "W" },
  { id: "archangels", name: "Saints Michael, Gabriel, and Raphael", feastDay: "09-29", feastName: "Feast of the Archangels", biography: "The three archangels named in Scripture: Michael (Who is like God?), the warrior who defeated Satan; Gabriel (Strength of God), who announced the Incarnation to Mary; Raphael (God heals), who guided Tobias. They serve as God's messengers and protectors.", quote: "Who is like God? (Michael) — Hail, full of grace! (Gabriel) — I am Raphael, one of the seven angels who stand before the Lord.", patronage: "Guardians, messengers, travelers", bornDied: "Angelic feast", canonization: "Angelic feast", imageGradient: "from-yellow-600 via-gold-500 to-amber-400", symbol: "M" },
  { id: "jerome", name: "Saint Jerome", feastDay: "09-30", feastName: "Memorial of Saint Jerome", biography: "A biblical scholar and Doctor of the Church, Jerome translated the Bible into Latin (the Vulgate), which became the standard Bible for the Western Church for 1500 years. Known for his fiery temperament and rigorous scholarship, he lived as an ascetic in Bethlehem.", quote: "Ignorance of Scripture is ignorance of Christ.", patronage: "Biblical scholars, translators, librarians", bornDied: "342–420", canonization: "Pre-congregation", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "J" },
  { id: "therese-lisieux", name: "Saint Thérèse of Lisieux", feastDay: "10-01", feastName: "Memorial of Saint Thérèse of the Child Jesus", biography: "A Carmelite nun who taught the 'Little Way' of spiritual childhood, doing small things with great love. Though she died at 24, her autobiography 'Story of a Soul' became a spiritual classic. She is a Doctor of the Church and co-patron of the missions.", quote: "What matters in life is not great deeds but great love.", patronage: "Missions, florists, aviators", bornDied: "1873–1897", canonization: "1925", imageGradient: "from-pink-500 via-pink-400 to-rose-300", symbol: "T" },
  { id: "guardian-angels", name: "The Guardian Angels", feastDay: "10-02", feastName: "Memorial of the Guardian Angels", biography: "The Church teaches that each person has a Guardian Angel appointed by God to protect and guide them throughout life. This feast celebrates the loving care of these angelic companions who 'always behold the face of the Father.'", quote: "He will command His angels concerning you, to guard you in all your ways.", patronage: "Travelers, protection", bornDied: "Angelic feast", canonization: "Angelic feast", imageGradient: "from-sky-400 via-sky-300 to-blue-200", symbol: "G" },
  { id: "francis-assisi", name: "Saint Francis of Assisi", feastDay: "10-04", feastName: "Feast of Saint Francis of Assisi", biography: "The son of a wealthy merchant who renounced all worldly goods to embrace poverty. Francis founded the Franciscan Order, received the stigmata, preached to birds, and wrote the Canticle of the Sun. His radical love for Christ and all creation transformed the medieval Church.", quote: "Preach the Gospel at all times. Use words if necessary.", patronage: "Animals, ecology, Italy", bornDied: "1181–1226", canonization: "1228", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "F" },
  { id: "faustina", name: "Saint Faustina Kowalska", feastDay: "10-05", feastName: "Memorial of Saint Faustina Kowalska", biography: "A Polish nun who received visions of the Divine Mercy, recording them in her diary. Jesus asked her to promote the devotion to Divine Mercy, including the Divine Mercy Chaplet and the Feast of Divine Mercy. She is the Apostle of Divine Mercy.", quote: "Jesus, I trust in You!", patronage: "Divine Mercy devotion, Poland", bornDied: "1905–1938", canonization: "2000", imageGradient: "from-white via-rose-100 to-rose-200", symbol: "F" },
  { id: "bruno", name: "Saint Bruno of Cologne", feastDay: "10-06", feastName: "Memorial of Saint Bruno of Cologne", biography: "Founder of the Carthusian Order, one of the strictest monastic orders in the Church. Bruno and six companions established the Grande Chartreuse in the French Alps, seeking silence, solitude, and contemplative prayer. The Carthusians continue to live his rule.", quote: "Blessed is the solitude that brings us closer to God.", patronage: "Carthusians, the contemplative life", bornDied: "1030–1101", canonization: "1623", imageGradient: "from-stone-800 via-stone-700 to-zinc-600", symbol: "B" },
  { id: "our-lady-rosary", name: "Our Lady of the Rosary", feastDay: "10-07", feastName: "Memorial of Our Lady of the Rosary", biography: "Instituted as the Feast of Our Lady of Victory by Pope St. Pius V after the Christian victory at Lepanto (1571), credited to the praying of the Rosary. The feast celebrates Mary's intercession through the Rosary and the power of meditative prayer on Christ's life.", quote: "Say the Rosary every day to obtain peace for the world.", patronage: "The Rosary, peace", bornDied: "Marian feast", canonization: "Feast established 1573", imageGradient: "from-blue-600 via-blue-500 to-indigo-400", symbol: "R" },
  { id: "john-xxiii", name: "Pope Saint John XXIII", feastDay: "10-11", feastName: "Memorial of Pope Saint John XXIII", biography: "Good Pope John convened the Second Vatican Council (1962–1965), which transformed the Church's engagement with the modern world. Known for his warmth, humor, and pastoral heart, he wrote the encyclical Pacem in Terris. He was canonized in 2014.", quote: "I am the pope, and I am called Giovanni. I am a good man, but I am nothing.", patronage: "Papal delegates, Vatican II", bornDied: "1881–1963", canonization: "2014", imageGradient: "from-white via-slate-100 to-gray-200", symbol: "J" },
  { id: "john-paul-ii", name: "Pope Saint John Paul II", feastDay: "10-22", feastName: "Memorial of Pope Saint John Paul II", biography: "The first Polish pope, Karol Wojtyła served for 27 years, one of the longest pontificates. He traveled extensively, championed human dignity, helped end communism in Europe, wrote extensively on theology of the body, and called the world to a 'new evangelization.'", quote: "Do not be afraid. Open wide the doors to Christ!", patronage: "World Youth Day, families", bornDied: "1920–2005", canonization: "2014", imageGradient: "from-blue-700 via-blue-600 to-indigo-500", symbol: "J" },
  { id: "ignatius-antioch", name: "Saint Ignatius of Antioch", feastDay: "10-17", feastName: "Memorial of Saint Ignatius of Antioch", biography: "Bishop of Antioch and Apostolic Father, Ignatius wrote seven letters to churches while being transported to Rome for martyrdom. His letters are a treasured witness to early Church theology, hierarchy, and Eucharistic belief. He was devoured by wild beasts in the Colosseum.", quote: "I am the wheat of God; let me be ground by the teeth of wild beasts, that I may become the pure bread of Christ.", patronage: "Church unity, Asia Minor", bornDied: "c. 35–108", canonization: "Pre-congregation", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "I" },
  { id: "luke", name: "Saint Luke the Evangelist", feastDay: "10-18", feastName: "Feast of Saint Luke the Evangelist", biography: "A physician and companion of St. Paul, Luke wrote the third Gospel and the Acts of the Apostles. His Gospel emphasizes Jesus' mercy, compassion for the poor and outcasts, and the role of women. He is a patron of doctors and artists.", quote: "For nothing will be impossible for God.", patronage: "Physicians, artists, surgeons", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-lime-700 via-lime-600 to-green-500", symbol: "L" },
  { id: "paul-cross", name: "Saint Paul of the Cross", feastDay: "10-20", feastName: "Memorial of Saint Paul of the Cross", biography: "Founder of the Passionists, Paul dedicated his life to spreading devotion to the Passion of Christ. He established monasteries and preached missions across Italy. The Passionists take a vow to promote the memory of Christ's suffering and death.", quote: "When we contemplate the Passion, we find a remedy for every spiritual ill.", patronage: "Missions, the Passionist Order", bornDied: "1694–1775", canonization: "1867", imageGradient: "from-violet-800 via-violet-700 to-purple-600", symbol: "P" },
  { id: "john-capistrano", name: "Saint John of Capistrano", feastDay: "10-23", feastName: "Memorial of Saint John of Capistrano", biography: "A Franciscan friar who preached throughout Europe, calling for reform and crusade. He led the Hungarian forces to victory at the Siege of Belgrade (1456). Known as the 'Soldier Saint,' he combined fervent preaching with military leadership.", quote: "Renew your faith, reform your lives, and trust in God.", patronage: "Military chaplains, jurists", bornDied: "1386–1456", canonization: "1690", imageGradient: "from-orange-700 via-orange-600 to-amber-500", symbol: "J" },
  { id: "anthony-claret", name: "Saint Anthony Mary Claret", feastDay: "10-24", feastName: "Memorial of Saint Anthony Mary Claret", biography: "Founder of the Missionary Sons of the Immaculate Heart of Mary (Claretians) and Archbishop of Santiago de Cuba. He was a prolific writer, publisher, and missionary who served as confessor to Queen Isabella II. He promoted devotion to the Eucharist and the Immaculate Heart.", quote: "To know Christ and to make Him known — this is my whole desire.", patronage: "Publishers, missionaries", bornDied: "1807–1870", canonization: "1950", imageGradient: "from-cyan-700 via-cyan-600 to-teal-500", symbol: "A" },
  { id: "simon-jude", name: "Saints Simon & Jude", feastDay: "10-28", feastName: "Feast of Saints Simon and Jude", biography: "Simon the Zealot and Jude Thaddeus were among the twelve apostles. Simon preached in Egypt and Persia. Jude, brother of James the Less, wrote the Epistle of Jude and is invoked as the patron of hopeless causes. Both were martyred in Persia.", quote: "In difficult times, pray to Saint Jude, the patron of impossible causes.", patronage: "Hopeless causes (Jude)", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-teal-700 via-teal-600 to-emerald-500", symbol: "S" },
  { id: "all-saints", name: "All Saints", feastDay: "11-01", feastName: "Solemnity of All Saints", biography: "The Church triumphant — all the saints in heaven, known and unknown — is celebrated on this solemnity. This feast honors every soul who has attained the beatific vision, reminding us of our universal call to holiness. It was first celebrated in the 4th century.", quote: "Rejoice and be glad, for your reward is great in heaven.", patronage: "The universal call to holiness", bornDied: "Solemnity", canonization: "Ancient feast", imageGradient: "from-yellow-700 via-gold-600 to-amber-500", symbol: "S" },
  { id: "all-souls", name: "Commemoration of All the Faithful Departed (All Souls)", feastDay: "11-02", feastName: "Commemoration of All the Faithful Departed", biography: "On this day, the Church prays for all the souls in purgatory who are being purified before entering heaven. Established by St. Odilo of Cluny in 998, the tradition of praying for the dead is rooted in the communion of saints and the hope of resurrection.", quote: "Eternal rest grant unto them, O Lord, and let perpetual light shine upon them.", patronage: "The faithful departed", bornDied: "Commemoration", canonization: "Ancient tradition", imageGradient: "from-violet-900 via-violet-800 to-purple-700", symbol: "P" },
  { id: "charles-borromeo", name: "Saint Charles Borromeo", feastDay: "11-04", feastName: "Memorial of Saint Charles Borromeo", biography: "Cardinal-Archbishop of Milan and a leading figure of the Counter-Reformation. Charles implemented the reforms of the Council of Trent, established seminaries, and cared for plague victims. His administrative and pastoral reforms revitalized the Church in northern Italy.", quote: "If you wish to judge well, you must first love well.", patronage: "Cardinals, seminarians", bornDied: "1538–1584", canonization: "1610", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "C" },
  { id: "leo-great", name: "Pope Saint Leo the Great", feastDay: "11-10", feastName: "Memorial of Pope Saint Leo the Great", biography: "Pope and Doctor of the Church, Leo famously confronted Attila the Hun and persuaded him to spare Rome. His Tome at the Council of Chalcedon (451) defined the two natures of Christ. He was a theologian, diplomat, and defender of orthodoxy.", quote: "Christian, recognize your dignity!", patronage: "Popes, liturgists", bornDied: "400–461", canonization: "Pre-congregation", imageGradient: "from-white via-slate-200 to-gray-300", symbol: "L" },
  { id: "martin-tours", name: "Saint Martin of Tours", feastDay: "11-11", feastName: "Memorial of Saint Martin of Tours", biography: "A Roman soldier who famously cut his cloak in half to share with a beggar, then received a vision of Christ. He became Bishop of Tours, founding monastic communities. One of the first non-martyred saints venerated in the West, he is a model of charity.", quote: "Lord, if Your people still need me, I do not refuse the work.", patronage: "Soldiers, the poor, France", bornDied: "316–397", canonization: "Pre-congregation", imageGradient: "from-blue-800 via-blue-700 to-indigo-600", symbol: "M" },
  { id: "josaphat", name: "Saint Josaphat", feastDay: "11-12", feastName: "Memorial of Saint Josaphat", biography: "A Basilian monk and Archbishop of Polotsk, Josaphat worked tirelessly for the unity of Eastern and Western Churches. He was martyred by a mob opposed to Church unity. He is the patron saint of Ukraine and a symbol of ecumenical reconciliation.", quote: "I am ready to die for the unity of the Church.", patronage: "Ukraine, ecumenism", bornDied: "1580–1623", canonization: "1867", imageGradient: "from-indigo-800 via-indigo-700 to-purple-600", symbol: "J" },
  { id: "albert-great", name: "Saint Albert the Great", feastDay: "11-15", feastName: "Memorial of Saint Albert the Great", biography: "A Dominican bishop and Doctor of the Church, Albert was a preeminent scientist, philosopher, and theologian of the 13th century. He was the teacher of Thomas Aquinas and pioneered the integration of Aristotelian philosophy with Christian theology.", quote: "The whole world is like a book written by the finger of God.", patronage: "Scientists, philosophers, students", bornDied: "1200–1280", canonization: "1931", imageGradient: "from-lime-800 via-lime-700 to-green-600", symbol: "A" },
  { id: "elizabeth-hungary", name: "Saint Elizabeth of Hungary", feastDay: "11-17", feastName: "Memorial of Saint Elizabeth of Hungary", biography: "A princess who lived a life of radical charity despite her royal status. After her husband's death, she became a Franciscan tertiary, building hospitals and serving the sick personally. Her selfless service to the poor and lepers exemplifies Christian love in action.", quote: "If we love God, we will love our neighbor; if we love our neighbor, we will love God.", patronage: "Bakers, the homeless, widows", bornDied: "1207–1231", canonization: "1235", imageGradient: "from-rose-700 via-rose-600 to-pink-500", symbol: "E" },
  { id: "dedication-basilicas", name: "Dedication of the Basilicas of Saints Peter and Paul", feastDay: "11-18", feastName: "Feast of the Dedication of the Basilicas of Saints Peter and Paul", biography: "Commemorates the dedication of the two great Roman basilicas built over the tombs of the apostles Peter (Vatican) and Paul (Ostian Way). These churches symbolize the universal Church founded on the apostolic witness and the unity of faith.", quote: "You are Peter, and upon this rock I will build my Church.", patronage: "The universal Church", bornDied: "Feast", canonization: "Ancient feast", imageGradient: "from-stone-700 via-stone-600 to-gray-500", symbol: "P" },
  { id: "catherine-alexandria", name: "Saint Catherine of Alexandria", feastDay: "11-25", feastName: "Memorial of Saint Catherine of Alexandria", biography: "A learned virgin and martyr of the early 4th century. Catherine was tortured on a spiked wheel for refusing to renounce her faith and was then beheaded. She is one of the Fourteen Holy Helpers and is invoked for wisdom and eloquence.", quote: "The wisdom of God confounds the wisdom of the wise.", patronage: "Philosophers, students, wheelwrights", bornDied: "d. 305", canonization: "Pre-congregation", imageGradient: "from-purple-700 via-purple-600 to-fuchsia-500", symbol: "C" },
  { id: "andrew", name: "Saint Andrew the Apostle", feastDay: "11-30", feastName: "Feast of Saint Andrew the Apostle", biography: "The first-called apostle, Andrew was a fisherman and brother of Peter. He brought Peter to Jesus and preached in Greece, where he was crucified on an X-shaped cross at Patras. He is the patron of Scotland, Russia, and Greece.", quote: "We have found the Messiah!", patronage: "Scotland, Russia, fishermen", bornDied: "1st century", canonization: "Pre-congregation", imageGradient: "from-blue-800 via-blue-700 to-indigo-600", symbol: "A" },
  { id: "nicholas", name: "Saint Nicholas of Myra", feastDay: "12-06", feastName: "Memorial of Saint Nicholas of Myra", biography: "Bishop of Myra in Asia Minor, Nicholas was known for his generosity, secretly giving gifts to the poor. He famously provided dowries for three impoverished sisters and defended orthodox Trinitarian doctrine at the Council of Nicaea (325). He is the basis for the Santa Claus tradition.", quote: "The giver of every good and perfect gift is God; we are merely His instruments.", patronage: "Children, sailors, the poor", bornDied: "d. 343", canonization: "Pre-congregation", imageGradient: "from-red-700 via-red-600 to-rose-500", symbol: "N" },
  { id: "ambrose", name: "Saint Ambrose of Milan", feastDay: "12-07", feastName: "Memorial of Saint Ambrose", biography: "Bishop of Milan and Doctor of the Church, Ambrose was a brilliant preacher and theologian. He baptized St. Augustine and converted the Emperor Theodosius. His liturgical reforms shaped Western liturgy, and his writings on moral theology remain influential.", quote: "If you are in Rome, live as the Romans do; if you are elsewhere, live as they do.", patronage: "Milan, bee keepers, candle makers", bornDied: "339–397", canonization: "Pre-congregation", imageGradient: "from-amber-700 via-amber-600 to-yellow-500", symbol: "A" },
  { id: "immaculate-conception", name: "The Immaculate Conception of the Blessed Virgin Mary", feastDay: "12-08", feastName: "Solemnity of the Immaculate Conception", biography: "The dogma proclaimed by Pope Pius IX in 1854 that Mary, from the first moment of her conception, was preserved free from Original Sin by the grace of Jesus Christ. This unique privilege prepared her to be the worthy Mother of God.", quote: "Hail, full of grace, the Lord is with you! Blessed are you among women.", patronage: "United States, the unborn", bornDied: "Marian feast", canonization: "Dogma defined 1854", imageGradient: "from-blue-500 via-blue-400 to-sky-300", symbol: "M" },
  { id: "juan-diego", name: "Our Lady of Guadalupe / St. Juan Diego", feastDay: "12-12", feastName: "Feast of Our Lady of Guadalupe", biography: "The Virgin Mary appeared to Juan Diego, an indigenous Mexican peasant, on Tepeyac Hill in 1531. Her image miraculously imprinted on his tilma became the most venerated icon in the Americas. The feast celebrates Mary's maternal love for all peoples and the unity of cultures.", quote: "Am I not here, I who am your mother? Are you not under my shadow and protection?", patronage: "The Americas, the unborn", bornDied: "1474–1548 / Appeared 1531", canonization: "Juan Diego canonized 2002", imageGradient: "from-green-700 via-green-600 to-emerald-500", symbol: "G" },
  { id: "lucy", name: "Saint Lucy", feastDay: "12-13", feastName: "Memorial of Saint Lucy", biography: "A young virgin martyr from Syracuse, Lucy was tortured and killed during Diocletian's persecution. Her name means 'light,' and she is invoked for eye troubles. She is one of the most revered early martyrs, mentioned in the Roman Canon.", quote: "The body is defiled only by the consent of the soul.", patronage: "Sight, the blind, eye ailments", bornDied: "283–304", canonization: "Pre-congregation", imageGradient: "from-yellow-600 via-gold-500 to-amber-400", symbol: "L" },
  { id: "john-cross", name: "Saint John of the Cross", feastDay: "12-14", feastName: "Memorial of Saint John of the Cross", biography: "A Spanish Carmelite mystic, poet, and Doctor of the Church. With St. Teresa of Avila, he reformed the Carmelite Order. His writings on the 'dark night of the soul' describe the soul's purification and union with God, and are masterpieces of mystical theology.", quote: "In the evening of life, we will be judged on love alone.", patronage: "Mystics, poets, contemplatives", bornDied: "1542–1591", canonization: "1726", imageGradient: "from-violet-900 via-violet-800 to-purple-700", symbol: "J" },
  { id: "teresa-avila", name: "Saint Teresa of Ávila", feastDay: "10-15", feastName: "Memorial of Saint Teresa of Ávila", biography: "A Spanish Carmelite nun, mystic, and Doctor of the Church. Teresa reformed the Carmelite Order, founded numerous convents, and wrote spiritual classics including 'The Interior Castle' and 'The Way of Perfection.' She is a master of contemplative prayer.", quote: "Let nothing disturb you, let nothing frighten you. All things pass away; God never changes.", patronage: "Sick people, Spain", bornDied: "1515–1582", canonization: "1622", imageGradient: "from-fuchsia-700 via-fuchsia-600 to-purple-500", symbol: "T" },
];

export function getSaintOfTheDay(date?: Date): Saint {
  const today = date || new Date();
  const mmdd = `${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;

  const saint = saints.find((s) => s.feastDay === mmdd);

  if (saint) return saint;

  return {
    id: "mary-mother-of-god",
    name: "Mary, Mother of God",
    feastDay: mmdd,
    feastName: "Memorial of the Blessed Virgin Mary",
    biography: "Today the Church honors the Blessed Virgin Mary under her universal title as Mother of God and our mother in faith. The Church invites us to reflect on Mary's faithful witness and her continuing intercession for all who seek her Son.",
    quote: "Blessed are you among women, and blessed is the fruit of your womb!",
    patronage: "All humanity",
    imageGradient: "from-blue-500 via-blue-400 to-sky-300",
    symbol: "M",
  };
}

export function getSaintByName(name: string): Saint | undefined {
  return saints.find(
    (s) => s.name.toLowerCase().includes(name.toLowerCase()) || s.id.includes(name.toLowerCase())
  );
}

export function getSaintsByMonth(month: number): Saint[] {
  const mm = String(month).padStart(2, "0");
  return saints.filter((s) => s.feastDay.startsWith(mm));
}

export function searchSaints(query: string): Saint[] {
  const q = query.toLowerCase();
  return saints.filter(
    (s) =>
      s.name.toLowerCase().includes(q) ||
      s.feastName.toLowerCase().includes(q) ||
      s.patronage.toLowerCase().includes(q)
  );
}

export default saints;
